const toNum = (s) => {
  if (s === undefined || s === null || s === '') return null;
  let t = String(s).replace(/[^\d.,\-]/g, '');
  if (!t) return null;
  const lc = t.lastIndexOf(','), ld = t.lastIndexOf('.');
  if (lc > ld && t.length - lc - 1 <= 2) t = t.replace(/\./g, '').replace(',', '.');
  else t = t.replace(/,/g, '');
  const n = parseFloat(t);
  return isNaN(n) ? null : n;
};
const MONTHS = { jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12 };
const toISO = (s) => {
  if (!s) return null;
  s = s.trim();
  let m = s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})$/);
  if (m) return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  m = s.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$/);
  if (m && MONTHS[m[2].toLowerCase()]) return `${m[3]}-${String(MONTHS[m[2].toLowerCase()]).padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  return null;
};
const grab = (re, text) => { const m = text.match(re); return m ? m[1].trim() : null; };
const grabLast = (re, text) => { const all = [...text.matchAll(re)]; return all.length ? all[all.length - 1][1].trim() : null; };

return $input.all().map((item) => {
  const text = (item.json.text || '').replace(/\r/g, '');
  const isPO = /purchase\s+order/i.test(text.split('\n').slice(0, 6).join(' ')) && !/^\s*invoice\s*$/im.test(text);
  const invoiceNumber = grab(/invoice\s*(?:no\.?|number|#)\s*[:\-]?\s*([A-Z0-9][A-Z0-9\-\/_.]*)/i, text);
  const poNumber = grab(/(?:\bPO|purchase\s+order)\s*(?:no\.?|number|#)\s*[:\-]?\s*([A-Z0-9][A-Z0-9\-\/_.]*)/i, text);
  const docType = isPO ? 'PURCHASE_ORDER' : 'INVOICE';
  const docNumber = isPO ? (poNumber || invoiceNumber) : (invoiceNumber || poNumber);
  const rawDate = grab(/(?:invoice\s*date|order\s*date|po\s*date|date)\s*[:\-]?\s*([0-9A-Za-z.,\/\- ]{6,20})/i, text);
  const rawDue = grab(/due\s*date\s*[:\-]?\s*([0-9A-Za-z.,\/\- ]{6,20})/i, text);
  const vendor = grab(/(?:vendor|supplier|from|seller)\s*[:\-]\s*(.+)/i, text);
  const billTo = grab(/(?:bill\s*to|buyer|ship\s*to)\s*[:\-]\s*(.+)/i, text);
  let currency = grab(/currency\s*[:\-]?\s*([A-Z]{3})/i, text) || grab(/\b(USD|IDR|EUR|GBP|SGD|AUD|CAD|JPY|MYR)\b/, text);
  if (!currency) currency = /Rp\.?\s*\d/.test(text) ? 'IDR' : (/\$\s*\d/.test(text) ? 'USD' : null);

  const lineRe = /^\s*(.+?)\s+(\d+(?:[.,]\d+)?)\s+([\d.,]+)\s+([\d.,]+)\s*$/;
  const lines = [];
  for (const row of text.split('\n')) {
    if (/^(sub\s*total|total|tax|vat|ppn|item|description)/i.test(row.trim())) continue;
    const m = row.match(lineRe);
    if (m) lines.push({ description: m[1].trim(), quantity: toNum(m[2]), unitPrice: toNum(m[3]), amount: toNum(m[4]) });
  }

  const subtotal = toNum(grab(/sub\s*total\s*[:\-]?\s*(?:[A-Z]{3}|\$|Rp\.?)?\s*([\d.,]+)/i, text));
  const tax = toNum(grab(/(?:tax|vat|ppn)[^\n:]*[:\-]\s*(?:[A-Z]{3}|\$|Rp\.?)?\s*([\d.,]+)\s*$/im, text));
  const total = toNum(grabLast(/\btotal(?:\s*(?:due|amount|payable))?\s*[:\-]?\s*(?:[A-Z]{3}|\$|Rp\.?)?\s*([\d.,]+)/gi, text));

  return { json: {
    documentType: docType, documentNumber: docNumber, invoiceNumber, poNumber,
    documentDate: toISO(rawDate), dueDate: toISO(rawDue), rawDate,
    vendor, billTo, currency, lines, subtotal, tax, total,
    email: item.json.email, textLength: text.length,
  } };
});

const TOLERANCE = 0.02;
const seen = $getWorkflowStaticData('global');
seen.processed = seen.processed || {};
const r2 = (n) => Math.round(n * 100) / 100;

return $input.all().map((item) => {
  const d = item.json;
  const errors = [], warnings = [];

  if (!d.textLength || d.textLength < 20) errors.push('No readable text in PDF. It may be a scanned image; use OCR or an AI extractor.');
  if (!d.documentNumber) errors.push('Missing document number.');
  if (!d.vendor) errors.push('Missing vendor name.');
  if (!d.documentDate) errors.push('Missing or unrecognised document date.');
  if (d.total === null || d.total === undefined) errors.push('Missing total amount.');
  else if (d.total <= 0) errors.push('Total must be greater than zero.');
  if (!d.currency) warnings.push('Currency not detected.');
  if (!d.lines.length) warnings.push('No line items detected.');

  if (d.lines.length) {
    const bad = d.lines.filter(l => l.quantity !== null && l.unitPrice !== null && l.amount !== null && Math.abs(l.quantity * l.unitPrice - l.amount) > TOLERANCE * Math.max(1, l.quantity));
    if (bad.length) errors.push(`Line math mismatch on: ${bad.map(b => b.description).join(', ')}.`);
    const sum = r2(d.lines.reduce((a, l) => a + (l.amount || 0), 0));
    if (d.subtotal !== null && Math.abs(sum - d.subtotal) > TOLERANCE) errors.push(`Line items sum (${sum}) differs from subtotal (${d.subtotal}).`);
  }
  if (d.subtotal !== null && d.total !== null) {
    const expected = r2(d.subtotal + (d.tax || 0));
    if (Math.abs(expected - d.total) > TOLERANCE) errors.push(`Subtotal + tax (${expected}) differs from total (${d.total}).`);
  }

  const key = `${d.documentType}|${d.vendor}|${d.documentNumber}`;
  if (d.documentNumber && seen.processed[key]) errors.push('Duplicate document (already processed).');

  const status = errors.length ? 'needs_review' : 'valid';
  if (status === 'valid' && d.documentNumber) seen.processed[key] = new Date().toISOString();

  return { json: { ...d, validation: { status, errors, warnings, checkedAt: new Date().toISOString() } } };
});

const esc = (v) => String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
const csvCell = (v) => { const s = String(v ?? ''); return /[",\n]/.test(s) ? `"${s.replace(/"/g,'""')}"` : s; };
const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const base = `${d.documentType.toLowerCase()}_${String(d.documentNumber).replace(/[^A-Za-z0-9_-]/g, '-')}`;

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<Document type="${esc(d.documentType)}">
  <Header>
    <Number>${esc(d.documentNumber)}</Number>
    <PONumber>${esc(d.poNumber)}</PONumber>
    <Date>${esc(d.documentDate)}</Date>
    <DueDate>${esc(d.dueDate)}</DueDate>
    <Vendor>${esc(d.vendor)}</Vendor>
    <BillTo>${esc(d.billTo)}</BillTo>
    <Currency>${esc(d.currency)}</Currency>
  </Header>
  <Lines>
${d.lines.map((l, i) => `    <Line number="${i + 1}">
      <Description>${esc(l.description)}</Description>
      <Quantity>${esc(l.quantity)}</Quantity>
      <UnitPrice>${esc(l.unitPrice)}</UnitPrice>
      <Amount>${esc(l.amount)}</Amount>
    </Line>`).join('\n')}
  </Lines>
  <Totals>
    <Subtotal>${esc(d.subtotal)}</Subtotal>
    <Tax>${esc(d.tax)}</Tax>
    <Total>${esc(d.total)}</Total>
  </Totals>
  <Source>
    <EmailFrom>${esc(d.email?.from)}</EmailFrom>
    <EmailSubject>${esc(d.email?.subject)}</EmailSubject>
    <FileName>${esc(d.email?.fileName)}</FileName>
  </Source>
</Document>
`;

  const header = ['document_type','document_number','po_number','date','due_date','vendor','currency','line_no','description','quantity','unit_price','line_amount','subtotal','tax','total'];
  const rows = (d.lines.length ? d.lines : [{}]).map((l, i) => [d.documentType,d.documentNumber,d.poNumber,d.documentDate,d.dueDate,d.vendor,d.currency,l.description ? i + 1 : '',l.description,l.quantity,l.unitPrice,l.amount,d.subtotal,d.tax,d.total].map(csvCell).join(','));
  const csv = [header.join(','), ...rows].join('\n') + '\n';

  const { email, textLength, rawDate, validation, ...clean } = d;
  const json = JSON.stringify({ ...clean, source: email, validation }, null, 2);

  const files = [[`${base}.xml`, xml, 'application/xml'], [`${base}.csv`, csv, 'text/csv'], [`${base}.json`, json, 'application/json']];
  for (const [name, content, mime] of files) {
    out.push({ json: { documentNumber: d.documentNumber, fileName: name, format: name.split('.').pop() }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(content, 'utf8'), name, mime) } });
  }
}
return out;

