const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const f = bin[key];
    const isPdf = (f.mimeType || '').includes('pdf') || (f.fileName || '').toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    out.push({
      json: {
        messageId: item.json.id,
        subject: item.json.subject || '',
        from: item.json.from?.value?.[0]?.address || item.json.from?.text || '',
        receivedAt: item.json.date || '',
        fileName: f.fileName || key,
      },
      binary: { data: f },
    });
  }
}
return out;

return $input.all().map((item, i) => {
  const m = $('Split PDF Attachments').itemMatching(i).json;
  return { json: { text: item.json.text || '', email: m } };
});
